# Part 7: Enemy Sprites (40x56)
L('// ===== ENEMY SPRITES (40x56) =====')
L('function drawSlime(c,frame,squish){const O=1,BD=2,BM=3,BL=4,BH=5,BS=6,SH=7,HL=8,EY=9,PD=10,PL=11,WH=12;const baseY=28+squish,hM=-squish*0.6,wM=squish*0.4,cx=20;c.ellipse(cx,baseY,12+wM,10+hM,BM);c.ellipse(cx-1,baseY-1,10+wM,8+hM,BL);c.ellipse(cx-2,baseY-2,7+wM,5+hM,BH);c.ellipse(cx+2,baseY+2,9+wM,6+hM,BD);c.set(cx-10-wM,baseY+5+hM,BM);c.set(cx-11-wM,baseY+6+hM,BD);c.set(cx+10+wM,baseY+5+hM,BM);c.set(cx+11+wM,baseY+6+hM,BD);c.set(cx-6+wM,baseY+7+hM,BM);c.set(cx-6+wM,baseY+8+hM,BD);c.set(cx+5-wM,baseY+7+hM,BM);c.set(cx+5-wM,baseY+8+hM,BD);c.set(cx-2,baseY+8+hM,BM);c.set(cx-2,baseY+9+hM,BD);c.set(cx+2,baseY+8+hM,BM);c.set(cx+2,baseY+9+hM,BD);c.set(cx-4,baseY-4+hM,SH);c.set(cx-3,baseY-5+hM,WH);c.set(cx-3,baseY-4+hM,SH);c.set(cx-2,baseY-4+hM,HL);c.set(cx-1,baseY-4+hM,HL);c.set(cx-4,baseY-1+hM,EY);c.set(cx-3,baseY-1+hM,WH);c.set(cx+3,baseY-1+hM,EY);c.set(cx+4,baseY-1+hM,WH);c.set(cx-3,baseY+1+hM,PD);c.set(cx+4,baseY+1+hM,PD);c.set(cx-2,baseY+3+hM,BD);c.set(cx-1,baseY+4+hM,BD);c.set(cx,baseY+4+hM,BD);c.set(cx+1,baseY+3+hM,BD);c.set(cx+2,baseY+3+hM,BD);c.dither(cx-6,baseY+1+hM,5,4,BM,BL);c.dither(cx+2,baseY+1+hM,5,4,BM,BD);c.outline(O)}')
L('function createSlimeSprite(){const idle=[];const sq=[0,-3,2,0];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawSlime(c,i,sq[i]);idle.push(c.toFrame())}const attack=[];const asq=[-4,3,-1,0];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawSlime(c,i,asq[i]);if(i===1){c.rect(6,22,6,4,4);c.set(6,22,5);c.set(7,21,5);c.set(8,20,5);c.set(6,23,2)}attack.push(c.toFrame())}const hurt=[];{const c1=new PixelCanvas(40,56);drawSlime(c1,0,2);hurt.push(c1.toFrame());hurt.push(flashFrame(hurt[0],8))}const death=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawSlime(c,0,i*4);death.push(c.toFrame())}return{id:"slime",palette:SP,animations:{idle:makeAnim("idle",idle,250,true),attack:makeAnim("attack",attack,120,false),hurt:makeAnim("hurt",hurt,100,false),death:makeAnim("death",death,200,false)}}}')

L('function drawWolf(c,f,legPhase,pounce){const O=1,FD=2,FM=3,FL=4,FH=5,BL=6,WH=7,EY=8,ER=9,CL=10,CD=11,NM=12,TG=13;const by=6+pounce,cx=20;c.ellipse(cx,26+by,13,7,FM);c.ellipse(cx,25+by,10,5,FL);c.ellipse(cx,24+by,6,3,FH);c.ellipse(cx,28+by,9,4,FD);c.ellipse(cx,29+by,9,2,BL);for(let i=0;i<8;i++){c.set(12+i*2,23+by,FL);c.set(13+i*2,24+by,FM)}c.dither(11,25+by,6,4,FM,FD);c.dither(25,25+by,6,4,FM,FD);c.ellipse(cx,22+by,6,5,FM);c.ellipse(cx,21+by,5,4,FL);c.ellipse(cx,23+by,5,3,FD);c.rect(3,22+by,5,3,FL);c.set(3,22+by,WH);c.set(4,21+by,FM);c.set(2,22+by,FH);c.set(3,22+by,NM);c.set(7,20+by,ER);c.set(8,20+by,EY);c.set(6,16+by,FM);c.set(7,16+by,FD);c.set(8,15+by,FM);c.set(9,15+by,FD);c.set(6,17+by,FL);c.set(8,17+by,FL);c.set(5,15+by,FH);c.set(9,14+by,FH);c.set(4,24+by,WH);c.set(5,24+by,WH);const lo=[Math.round(Math.sin(legPhase)*2),Math.round(Math.sin(legPhase+Math.PI)*2),Math.round(Math.sin(legPhase+Math.PI)*2),Math.round(Math.sin(legPhase)*2)];const lxs=[14,18,26,30];for(let i=0;i<4;i++){c.line(lxs[i],33+by,lxs[i]-3,40+lo[i]+by,FM);c.set(lxs[i]-3,40+lo[i]+by,BD)}c.set(33,22+by,FM);c.set(34,21+by,FL);c.set(35,20+by,FH);c.set(34,20+by,FM);c.set(36,19+by,TG);c.set(35,18+by,FL);c.outline(O)}')
L('function createWolfSprite(){const idle=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawWolf(c,i,0,0);idle.push(c.toFrame())}const walk=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawWolf(c,i,i*Math.PI/2,0);walk.push(c.toFrame())}const attack=[];const py=[-3,-6,3,0];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawWolf(c,i,0,py[i]);attack.push(c.toFrame())}const hurt=[];{const c1=new PixelCanvas(40,56);drawWolf(c1,0,0,0);hurt.push(c1.toFrame());hurt.push(flashFrame(hurt[0],9))}const death=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawWolf(c,0,0,0);const sf=shiftFrame(c.toFrame(),0,i*3);const c2=new PixelCanvas(40,56);for(let y=0;y<56;y++)for(let x=0;x<40;x++)c2.px[y][x]=sf.data[y][x];death.push(c2.toFrame())}return{id:"wolf",palette:WP,animations:{idle:makeAnim("idle",idle,200,true),walk:makeAnim("walk",walk,120,true),attack:makeAnim("attack",attack,100,false),hurt:makeAnim("hurt",hurt,100,false),death:makeAnim("death",death,200,false)}}}')

L('function drawTreeSpirit(c,f,sway){const O=1,BKD=2,BKM=3,BKLT=4,BKHL=5,LFD=6,LFM=7,LFL=8,LFHL=9,GL=10,GLH=11,BKLN=12;const sx=sway,cx=20;c.rect(cx-6+sx,14,12,22,BKM);c.rect(cx-5+sx,14,10,20,BKLT);c.rect(cx-4+sx,14,6,17,BKHL);c.rect(cx+8+sx,22,6,18,BKD);c.line(cx-5+sx,16,cx-5+sx,34,BKD);c.line(cx+5+sx,15,cx+5+sx,33,BKD);c.set(cx-6+sx,26,BKLN);c.set(cx-2+sx,32,BKLN);c.set(cx+1+sx,28,BKLN);c.set(cx-5+sx,44,BKLN);c.set(cx+2+sx,44,BKLN);c.set(cx-3+sx,54,BKLN);c.rect(cx-16+sx,34,10,6,BKM);c.rect(cx+8+sx,34,10,6,BKM);c.rect(cx-14+sx,34,6,4,BKLT);c.rect(cx+10+sx,34,6,4,BKLT);c.set(cx-16+sx,39,BKD);c.set(cx+19+sx,39,BKD);c.line(cx-16+sx,39,cx-22+sx,44,BKM);c.set(cx-22+sx,44,BKLT);c.line(cx+19+sx,39,cx+26+sx,44,BKM);c.set(cx+26+sx,44,BKLT);c.ellipse(cx+sx,8,11,8,LFM);c.ellipse(cx-1+sx,7,9,6,LFL);c.ellipse(cx-2+sx,6,6,4,LFHL);c.ellipse(cx+3+sx,10,8,5,LFD);c.set(cx-8+sx,5,LFM);c.set(cx-7+sx,4,LFL);c.set(cx-6+sx,3,LFHL);c.set(cx+9+sx,4,LFM);c.set(cx+10+sx,5,LFD);c.set(cx+11+sx,6,LFD);c.set(cx-14+sx,7,LFD);c.set(cx+12+sx,8,LFD);c.line(cx-12+sx,18,cx-18+sx,12,BKM);c.set(cx-18+sx,8,LFM);c.line(cx+12+sx,18,cx+18+sx,12,BKM);c.set(cx+18+sx,8,LFM);c.set(cx-4+sx,26,GL);c.set(cx-3+sx,26,GLH);c.set(cx+2+sx,26,GL);c.set(cx+3+sx,26,GLH);c.set(cx-2+sx,32,BKD);c.set(cx-1+sx,32,BKD);c.set(cx,32,BKD);c.set(cx+1+sx,32,BKD);c.outline(O)}')
L('function createTreeSpiritSprite(){const idle=[];const sw=[0,1.5,-1.5,0];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawTreeSpirit(c,i,sw[i]);idle.push(c.toFrame())}const attack=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawTreeSpirit(c,i,0);if(i===1){c.line(5,8,1,16,3);c.set(1,17,3);c.set(0,16,2)}if(i===2){c.line(35,8,39,16,3);c.set(39,17,3);c.set(40,16,2)}attack.push(c.toFrame())}const hurt=[];{const c1=new PixelCanvas(40,56);drawTreeSpirit(c1,0,0);hurt.push(c1.toFrame());hurt.push(flashFrame(hurt[0],9))}const death=[];for(let i=0;i<4;i++){const c=new PixelCanvas(40,56);drawTreeSpirit(c,0,0);const sf=shiftFrame(c.toFrame(),0,i*2);const c2=new PixelCanvas(40,56);for(let y=0;y<56;y++)for(let x=0;x<40;x++)c2.px[y][x]=sf.data[y][x];death.push(c2.toFrame())}return{id:"tree_spirit",palette:TP,animations:{idle:makeAnim("idle",idle,300,true),attack:makeAnim("attack",attack,150,false),hurt:makeAnim("hurt",hurt,100,false),death:makeAnim("death",death,250,false)}}}')

